package org.example.kalkulationsprogramm.domain.einkauf;
import jakarta.persistence.*;import java.time.*;import java.util.*;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;
@Entity @Table(name="einkauf_bestellbestaetigung")
public class BestellBestaetigung {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="bestellung_id",nullable=false)private EinkaufBestellung bestellung;@Column(name="dokument_id",nullable=false)private Long dokumentId;@Column(nullable=false)private LocalDate datum;@Column(name="liefertermin")private LocalDate liefertermin;@JdbcTypeCode(SqlTypes.JSON)@Column(name="positionen_snapshot",nullable=false,columnDefinition="json")private List<Map<String,Object>> positionen;@Column(name="abweichung",nullable=false)private boolean abweichung;@Column(name="akteur_id",nullable=false)private Long akteurId;@Column(name="erfasst_am",nullable=false)private Instant erfasstAm=Instant.now();protected BestellBestaetigung(){}public BestellBestaetigung(EinkaufBestellung b,Long d,LocalDate date,LocalDate delivery,List<Map<String,Object>> p,boolean diff,Long actor){bestellung=b;dokumentId=d;datum=date;liefertermin=delivery;positionen=List.copyOf(p);abweichung=diff;akteurId=actor;}public Long getId(){return id;}public boolean isAbweichung(){return abweichung;}public Long getDokumentId(){return dokumentId;}
public LocalDate getDatum(){return datum;}public LocalDate getLiefertermin(){return liefertermin;}public List<Map<String,Object>> getPositionen(){return List.copyOf(positionen);}
}
